import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
void main() => runApp(const MaterialApp(home: SearchPostsPage(), debugShowCheckedModeBanner: false));
class SearchPostsPage extends StatefulWidget { const SearchPostsPage({super.key}); @override State<SearchPostsPage> createState() => _SearchPostsPageState(); }
class _SearchPostsPageState extends State<SearchPostsPage> { late Future<List<dynamic>> future; final controller = TextEditingController(); String query = ''; @override void initState() { super.initState(); future = fetch(); } Future<List<dynamic>> fetch() async { final r = await http.get(Uri.parse('https://jsonplaceholder.typicode.com/posts')); if (r.statusCode != 200) throw Exception('HTTP ${r.statusCode}'); return jsonDecode(r.body) as List<dynamic>; } @override void dispose() { controller.dispose(); super.dispose(); }
 @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Q12: Search API data')), body: Column(children: [Padding(padding: const EdgeInsets.all(12), child: TextField(controller: controller, onChanged: (v) => setState(() => query = v.toLowerCase()), decoration: InputDecoration(labelText: 'Search post titles', prefixIcon: const Icon(Icons.search), suffixIcon: IconButton(onPressed: () { controller.clear(); setState(() => query = ''); }, icon: const Icon(Icons.clear)), border: const OutlineInputBorder()))), Expanded(child: FutureBuilder<List<dynamic>>(future: future, builder: (context, s) { if (s.connectionState == ConnectionState.waiting) return const Center(child: CircularProgressIndicator()); if (s.hasError) return Center(child: Text('Error: ${s.error}')); final posts = s.data!.where((p) => '${p['title']}'.toLowerCase().contains(query)).toList(); if (posts.isEmpty) return const Center(child: Text('No matching posts')); return ListView.builder(itemCount: posts.length, itemBuilder: (context, i) => ListTile(title: Text('${posts[i]['title']}'), subtitle: Text('Post ID ${posts[i]['id']}'))); }))]));
}
